import { Component, computed, inject, input, signal, viewChild } from '@angular/core';
import { rxResource } from '@angular/core/rxjs-interop';
import { RouterLink } from '@angular/router';
import { ClientContacts } from '../contacts/client-contacts';
import { Contact } from '../contacts/contact.service';
import { ClientPaymentForm } from '../payments/client-payment';
import { ClientProjects } from '../projects/client-projects';
import { ClientService } from './client.service';

// A single client's page: their name, email and main contact, a link to their statement, a form to record a lump payment split across their invoices, counts of their projects and contacts, their contacts, and the projects being done for them.
@Component({
  selector: 'app-client-detail',
  imports: [RouterLink, ClientContacts, ClientProjects, ClientPaymentForm],
  styles: `
    .client-badges {
      display: flex;
      gap: 1rem;
      padding: 0;
      list-style: none;
    }
  `,
  template: `
    <a routerLink="/clients" data-testid="client-back">Back to clients</a>
    @if (client.error()) {
      <p role="alert" data-testid="client-error">Could not load the client.</p>
    } @else if (client.value(); as c) {
      <h1 data-testid="client-detail-name">{{ c.name }}</h1>
      <p>Email: <span data-testid="client-detail-email">{{ c.email }}</span></p>
      <p>
        Main contact:
        @if (c.primaryContact; as primary) {
          <span data-testid="client-primary-contact">{{ primary.name }}</span>
        } @else {
          <span data-testid="client-primary-contact-none">None chosen</span>
        }
      </p>
      @if (summary.hasValue()) {
        <ul class="client-badges" aria-label="At a glance" data-testid="client-badges">
          <li>
            Jobs: <span data-testid="client-projects-count">{{ summary.value().projectCount }}</span>
          </li>
          <li>
            Contacts: <span data-testid="client-contacts-count">{{ summary.value().contactCount }}</span>
          </li>
        </ul>
      }
      <p>
        <a [routerLink]="['/clients', clientId(), 'statement']" data-testid="client-statement-open">View statement</a>
      </p>
      <p>
        <button
          type="button"
          data-testid="client-record-payment"
          aria-controls="client-payment-panel"
          [attr.aria-expanded]="recordingPayment()"
          (click)="recordingPayment.set(!recordingPayment())"
        >
          {{ recordingPayment() ? 'Close payment form' : 'Record a payment' }}
        </button>
      </p>
      <div id="client-payment-panel">
        @if (recordingPayment()) {
          <app-client-payment [clientId]="clientId()" (recorded)="paymentRecorded()" />
        }
        @if (paymentSaved()) {
          <p role="status" data-testid="client-payment-recorded">Payment recorded.</p>
        }
      </div>
      <app-client-contacts
        [clientId]="clientId()"
        (contactAdded)="contactAdded()"
        (primaryChanged)="primaryChanged($event)"
      />
      <app-client-projects [clientId]="clientId()" />
    }
  `,
})
export class ClientDetail {
  private readonly service = inject(ClientService);

  /** Bound from the `:id` route parameter. */
  readonly id = input.required<string>();
  protected readonly clientId = computed(() => Number(this.id()));

  protected readonly client = rxResource({
    params: () => this.clientId(),
    stream: ({ params }) => this.service.get(params),
  });

  protected readonly summary = rxResource({
    params: () => this.clientId(),
    stream: ({ params }) => this.service.summary(params),
  });

  protected readonly recordingPayment = signal(false);
  protected readonly paymentSaved = signal(false);
  private readonly paymentForm = viewChild(ClientPaymentForm);

  /** Resolves to true once any payment being recorded has been saved, so the page can be left safely. */
  async canLeave(): Promise<boolean> {
    await this.paymentForm()?.settled();
    return true;
  }

  protected paymentRecorded(): void {
    this.recordingPayment.set(false);
    this.paymentSaved.set(true);
    this.client.reload();
  }

  protected contactAdded(): void {
    this.summary.reload();
    // The first contact added becomes the main contact.
    if (!this.client.value()?.primaryContact) {
      this.client.reload();
    }
  }

  protected primaryChanged(contact: Contact): void {
    this.client.update((c) => c && { ...c, primaryContact: { id: contact.id, name: contact.name } });
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

export interface Client {
  id: number;
  name: string;
  email: string;
  archived: boolean;
  /** The client's main contact; null until one is chosen. */
  primaryContact: { id: number; name: string } | null;
  /** What is left to pay on the client's sent, not yet fully paid invoices. */
  outstanding: number;
}

/** At-a-glance counts of what one client has. */
export interface ClientSummary {
  projectCount: number;
  contactCount: number;
}

export type NewClient = Omit<Client, 'id' | 'archived' | 'primaryContact' | 'outstanding'>;

@Injectable({ providedIn: 'root' })
export class ClientService {
  private readonly http = inject(HttpClient);

  list(includeArchived = false): Observable<Client[]> {
    return this.http.get<Client[]>('/api/clients', { params: { includeArchived } });
  }

  get(id: number): Observable<Client> {
    return this.http.get<Client>(`/api/clients/${id}`);
  }

  summary(id: number): Observable<ClientSummary> {
    return this.http.get<ClientSummary>(`/api/clients/${id}/summary`);
  }

  create(client: NewClient): Observable<Client> {
    return this.http.post<Client>('/api/clients', client);
  }

  update(id: number, client: NewClient): Observable<Client> {
    return this.http.put<Client>(`/api/clients/${id}`, client);
  }

  archive(id: number): Observable<Client> {
    return this.http.post<Client>(`/api/clients/${id}/archive`, null);
  }

  restore(id: number): Observable<Client> {
    return this.http.post<Client>(`/api/clients/${id}/restore`, null);
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

export interface TopClient {
  id: number;
  name: string;
  outstanding: number;
}

export interface DashboardSummary {
  clients: number;
  projects: number;
  outstanding: number;
  overdue: number;
  topClients: TopClient[];
}

@Injectable({ providedIn: 'root' })
export class DashboardService {
  private readonly http = inject(HttpClient);

  summary(): Observable<DashboardSummary> {
    return this.http.get<DashboardSummary>('/api/dashboard');
  }
}
import { CurrencyPipe } from '@angular/common';
import { Component, computed, inject, signal } from '@angular/core';
import { DashboardService, DashboardSummary } from './dashboard.service';

// Dashboard page: how many clients and projects there are, and the total still owed (what is left
// to pay on invoices that have been sent but not yet fully paid; drafts are not counted), and how
// many of those sent invoices are past their due date. Also lists the top five clients ranked by
// what they still owe.
@Component({
  selector: 'app-dashboard',
  imports: [CurrencyPipe],
  template: `
    <h1>Dashboard</h1>

    @if (loadError()) {
      <p role="alert" data-testid="dashboard-error">{{ loadError() }}</p>
    } @else if (summary(); as s) {
      <dl data-testid="dashboard-summary">
        <div>
          <dt>Clients</dt>
          <dd data-testid="dashboard-clients-count">{{ s.clients }}</dd>
        </div>
        <div>
          <dt>Jobs</dt>
          <dd data-testid="dashboard-projects-count">{{ s.projects }}</dd>
        </div>
        <div>
          <dt>Outstanding</dt>
          <dd data-testid="dashboard-outstanding-total">{{ outstanding() | currency: 'USD' : 'symbol' : '1.2-2' : 'en-US' }}</dd>
        </div>
        <div>
          <dt>Overdue invoices</dt>
          <dd data-testid="dashboard-overdue-count">{{ s.overdue }}</dd>
        </div>
      </dl>

      <section data-testid="dashboard-top-clients" aria-labelledby="dashboard-top-clients-heading">
        <h2 id="dashboard-top-clients-heading">Top clients by amount owed</h2>
        @if (s.topClients.length) {
          <ol>
            @for (c of s.topClients; track c.id) {
              <li [attr.data-testid]="'top-client-row-' + c.id">
                <span data-testid="top-client-name">{{ c.name }}</span>:
                <span data-testid="top-client-amount">{{ c.outstanding | currency: 'USD' : 'symbol' : '1.2-2' : 'en-US' }}</span>
              </li>
            }
          </ol>
        } @else {
          <p data-testid="dashboard-top-clients-empty">No clients owe anything.</p>
        }
      </section>
    } @else {
      <p data-testid="dashboard-loading">Loading…</p>
    }
  `,
})
export class Dashboard {
  protected readonly summary = signal<DashboardSummary | null>(null);
  protected readonly loadError = signal<string | null>(null);
  protected readonly outstanding = computed(() => this.summary()?.outstanding ?? 0);

  constructor() {
    inject(DashboardService)
      .summary()
      .subscribe({
        next: (s) => this.summary.set(s),
        error: () => this.loadError.set('Could not load the dashboard. Please try again.'),
      });
  }
}

