package net.officefloor.hq.app.invoice;

import java.math.BigDecimal;
import java.time.LocalDate;

/** An invoice, with how much of it is still left to pay after the payments made against it (nothing once void). */
public record InvoiceResponse(Long id, Long projectId, BigDecimal amount, InvoiceStatus status,
        LocalDate issuedDate, LocalDate dueDate, BigDecimal amountDue) {

    static InvoiceResponse from(Invoice invoice, BigDecimal paid) {
        return new InvoiceResponse(invoice.getId(), invoice.getProject().getId(), invoice.getAmount(),
                invoice.getStatus(), invoice.getIssuedDate(), invoice.getDueDate(),
                invoice.amountDue(paid));
    }
}
package net.officefloor.hq.app.invoice;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;

/**
 * A single invoice together with the line items it is built from: their subtotal, the percentage
 * discount and what it takes off, the sales tax percentage and what it adds after the discount, and
 * the amount owed including that tax.
 */
public record InvoiceDetailResponse(Long id, Long projectId, BigDecimal amount, BigDecimal subtotal,
        BigDecimal discountPct, BigDecimal discount, BigDecimal taxPct, BigDecimal tax, InvoiceStatus status, LocalDate issuedDate,
        LocalDate dueDate, List<LineItemResponse> lineItems) {

    static InvoiceDetailResponse from(Invoice invoice) {
        return new InvoiceDetailResponse(invoice.getId(), invoice.getProject().getId(), invoice.getAmount(),
                invoice.getSubtotal(), invoice.getDiscountPct(), invoice.getDiscount(),
                invoice.getTaxPct(), invoice.getTax(),
                invoice.getStatus(), invoice.getIssuedDate(), invoice.getDueDate(),
                invoice.getLineItems().stream().map(LineItemResponse::from).toList());
    }
}
package net.officefloor.hq.app.project;

import java.math.BigDecimal;

/**
 * A project's budget, how much has been invoiced against it (every invoice sent, whether paid or
 * not; drafts are not yet invoiced) and what is left of it. Budget and remaining are null when no
 * budget is set.
 */
public record ProjectBudgetResponse(BigDecimal budget, BigDecimal invoiced, BigDecimal remaining) {

    static ProjectBudgetResponse of(BigDecimal budget, BigDecimal invoiced) {
        return new ProjectBudgetResponse(budget, invoiced, budget == null ? null : budget.subtract(invoiced));
    }
}
